    45	function renameWithRetry(
    46		fsImpl: AtomicJsonFs,
    47		sourcePath: string,
    48		targetPath: string,
    49		retryDelaysMs: readonly number[],
    50		wait: (delayMs: number) => void,
    51	): void {
    52		for (let attempt = 0; ; attempt++) {
    53			try {
    54				fsImpl.renameSync(sourcePath, targetPath);
    55				return;
    56			} catch (error) {
    57				const delayMs = retryDelaysMs[attempt];
